f=s[s.parsed.notna() & s.rate.notna()].copy().sort_values(['employee_id','parsed'])
def period(d):
 first=d.replace(day=1);start=first+pd.Timedelta(days=(1-first.weekday())%7)
 return (d if d>=start else first-pd.Timedelta(days=1)).strftime('%Y-%m')
f['period']=f.parsed.map(period);f['wages']=f.hours_worked*f.rate;f['computed']=f.groupby(['employee_id','period']).wages.cumsum();f['difference']=f.salary_amount-f.computed
print('\nCOUNT',len(f),'RESIDUAL COUNTS\n',f.difference.value_counts().to_string())
print('\nRESIDUAL ROWS\n',f[f.difference!=0].to_string(index=False))
print('\nATTENDANCE MISSING ON TUESDAYS')
for d in pd.date_range(f.parsed.min(),f.parsed.max()):
 if d.weekday()==1:
